contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(amount == 10);
        require(address(this).balance >= amount);

        uint potBefore = c.pot();
        uint balBefore = address(this).balance;

        c.play{value: amount}();

        uint balAfter = address(this).balance;
        uint potAfter = c.pot();

        // Either the player lost (balance and pot each +10), or the player won:
        // the full previous pot is paid out to this contract, pot resets to 0,
        // and the fee comes back to this contract since it is also the bank.
        assert(
            (balAfter == balBefore + amount && potAfter == potBefore + amount)
            ||
            (balAfter == balBefore + potBefore && potAfter == 0)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(amount == 10);
        require(address(this).balance >= amount);

        uint potBefore = c.pot();
        uint balBefore = address(this).balance;

        c.play{value: amount}();

        uint potAfter = c.pot();
        uint balAfter = address(this).balance;

        // Loss: no payout, the caller paid exactly the 10-wei ticket and the pot grew by 10.
        // Win: pot resets to 0 and the caller is paid the whole pot minus the 1-wei fee,
        // but receives the fee back as the bank, so it never ends up poorer than before.
        assert(
            (potAfter == potBefore + amount && balAfter == balBefore - amount)
            ||
            (potAfter == 0 && balAfter >= balBefore)
        );
    }

    receive() external payable {}
}
